class Solution {
public:
    string interpret(string command) {
        string result;
        int i = 0;
        int n = command.size();
        while (i < n) {
            if (command[i] == 'G') {
                result += 'G';
                i += 1;
            } else if (command[i] == '(') {
                if (i + 1 < n && command[i + 1] == ')') {
                    result += 'o';
                    i += 2;
                } else {
                    result += "al";
                    i += 4;
                }
            }
        }
        return result;
    }
};
